  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    errors.push("Date must be YYYY-MM-DD format");
  } else {
    const d = new Date(date);
    if (isNaN(d.getTime())) {
      errors.push("Invalid date");
    }
  }
